        VALUES (v_id_lot, v_numeros(i), v_0(i), v_1(i), v_2(i), v_3(i), v_4(i), v_5(i), v_6(i), v_7(i), v_8(i));
    IF SQL%ROWCOUNT <> 71 THEN
        RAISE_APPLICATION_ERROR(-20003, 'Nombre de lignes insérées incorrect.');
    END IF;
EXCEPTION
    WHEN e_rejets THEN
        FOR j IN 1 .. SQL%BULK_EXCEPTIONS.COUNT LOOP
            DBMS_OUTPUT.PUT_LINE('REJET brut_ressource, numero_ligne=' || (28500 + SQL%BULK_EXCEPTIONS(j).ERROR_INDEX)
                || ' : ' || SQLERRM(-SQL%BULK_EXCEPTIONS(j).ERROR_CODE));
        END LOOP;
        ROLLBACK;
        RAISE;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('ECHEC brut_ressource, bloc 28501-28571 : ' || SQLERRM);
        ROLLBACK;
        RAISE;
END;
/

PROMPT FIN cours.csv : 28571 lignes insérées, en attente du COMMIT final
